def max_segments(n, k, arr):
    def flip(i):
        return arr[i] ^ ((1 << k) - 1)

    res = 0
    current_xor = 0

    for i in range(n):
        current_xor ^= arr[i]
        if current_xor != 0:
            res += 1
        else:
            if i < n - 1:
                current_xor ^= flip(i + 1)
                res += 1

    return res

